import React, { useState, useEffect } from 'react';
import { DollarSign, Calendar, Check, Clock, AlertCircle, Download, Search } from 'lucide-react';

const PaymentHistory = ({ businessId }) => {
  const [payments, setPayments] = useState([]);
  const [loading, setLoading] = useState(true);
  const [filter, setFilter] = useState('all');
  const [searchTerm, setSearchTerm] = useState('');

  useEffect(() => {
    loadPayments();
  }, [businessId]);

  const loadPayments = async () => {
    setLoading(true);
    // Mock data for now - will connect to Supabase
    const mockPayments = [
      {
        id: 1,
        invoice_number: 'INV-000001',
        customer_name: 'Acme Corp',
        amount: 2500.00,
        payment_date: '2024-01-15',
        payment_method: 'Bank Transfer',
        status: 'completed',
        reference: 'TRX-001234'
      },
      {
        id: 2,
        invoice_number: 'INV-000002',
        customer_name: 'Tech Solutions',
        amount: 3750.00,
        payment_date: '2024-01-20',
        payment_method: 'Credit Card',
        status: 'completed',
        reference: 'CC-567890'
      },
      {
        id: 3,
        invoice_number: 'INV-000003',
        customer_name: 'Global Industries',
        amount: 5000.00,
        payment_date: null,
        due_date: '2024-02-01',
        payment_method: null,
        status: 'pending',
        reference: null
      },
      {
        id: 4,
        invoice_number: 'INV-000004',
        customer_name: 'Digital Agency',
        amount: 1800.00,
        payment_date: null,
        due_date: '2024-01-25',
        payment_method: null,
        status: 'overdue',
        reference: null
      }
    ];
    setPayments(mockPayments);
    setLoading(false);
  };

  const getStatusColor = (status) => {
    switch (status) {
      case 'completed':
        return 'bg-green-500';
      case 'pending':
        return 'bg-yellow-500';
      case 'overdue':
        return 'bg-red-500';
      default:
        return 'bg-gray-500';
    }
  };

  const getStatusIcon = (status) => {
    switch (status) {
      case 'completed':
        return <Check size={16} />;
      case 'pending':
        return <Clock size={16} />;
      case 'overdue':
        return <AlertCircle size={16} />;
      default:
        return null;
    }
  };

  const filteredPayments = payments.filter(payment => {
    const matchesFilter = filter === 'all' || payment.status === filter;
    const matchesSearch = payment.customer_name.toLowerCase().includes(searchTerm.toLowerCase()) ||
                          payment.invoice_number.toLowerCase().includes(searchTerm.toLowerCase());
    return matchesFilter && matchesSearch;
  });

  const totalReceived = payments
    .filter(p => p.status === 'completed')
    .reduce((sum, p) => sum + p.amount, 0);

  const totalPending = payments
    .filter(p => p.status === 'pending')
    .reduce((sum, p) => sum + p.amount, 0);

  const totalOverdue = payments
    .filter(p => p.status === 'overdue')
    .reduce((sum, p) => sum + p.amount, 0);

  if (loading) {
    return (
      <div className="bg-gray-800 rounded-xl p-6">
        <div className="animate-pulse">
          <div className="h-8 bg-gray-700 rounded w-1/4 mb-4"></div>
          <div className="space-y-3">
            <div className="h-12 bg-gray-700 rounded"></div>
            <div className="h-12 bg-gray-700 rounded"></div>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="bg-gray-800 rounded-xl p-6">
      <div className="flex justify-between items-center mb-6">
        <h2 className="text-xl font-bold text-white">Payment History</h2>
        <button className="flex items-center gap-2 px-4 py-2 bg-purple-500 text-white rounded-lg hover:bg-purple-600 transition-colors">
          <Download size={18} />
          Export
        </button>
      </div>

      <div className="grid grid-cols-3 gap-4 mb-6">
        <div className="bg-gray-700 rounded-lg p-4">
          <div className="flex items-center gap-2 text-green-400 mb-2">
            <DollarSign size={20} />
            <span className="text-sm">Received</span>
          </div>
          <p className="text-2xl font-bold text-white">
            ${totalReceived.toLocaleString()}
          </p>
        </div>
        <div className="bg-gray-700 rounded-lg p-4">
          <div className="flex items-center gap-2 text-yellow-400 mb-2">
            <Clock size={20} />
            <span className="text-sm">Pending</span>
          </div>
          <p className="text-2xl font-bold text-white">
            ${totalPending.toLocaleString()}
          </p>
        </div>
        <div className="bg-gray-700 rounded-lg p-4">
          <div className="flex items-center gap-2 text-red-400 mb-2">
            <AlertCircle size={20} />
            <span className="text-sm">Overdue</span>
          </div>
          <p className="text-2xl font-bold text-white">
            ${totalOverdue.toLocaleString()}
          </p>
        </div>
      </div>

      <div className="flex gap-4 mb-4">
        <div className="flex-1 relative">
          <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400" size={20} />
          <input
            type="text"
            placeholder="Search by customer or invoice..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="w-full pl-10 pr-4 py-2 bg-gray-700 border border-gray-600 rounded-lg text-white placeholder-gray-400 focus:outline-none focus:border-purple-500"
          />
        </div>
        <select
          value={filter}
          onChange={(e) => setFilter(e.target.value)}
          className="px-4 py-2 bg-gray-700 border border-gray-600 rounded-lg text-white focus:outline-none focus:border-purple-500"
        >
          <option value="all">All Payments</option>
          <option value="completed">Completed</option>
          <option value="pending">Pending</option>
          <option value="overdue">Overdue</option>
        </select>
      </div>

      <div className="overflow-x-auto">
        <table className="w-full">
          <thead>
            <tr className="text-left text-gray-400 text-sm">
              <th className="pb-3">Invoice</th>
              <th className="pb-3">Customer</th>
              <th className="pb-3">Amount</th>
              <th className="pb-3">Date</th>
              <th className="pb-3">Method</th>
              <th className="pb-3">Status</th>
              <th className="pb-3">Reference</th>
            </tr>
          </thead>
          <tbody className="text-white">
            {filteredPayments.map((payment) => (
              <tr key={payment.id} className="border-t border-gray-700">
                <td className="py-3">
                  <span className="font-mono text-sm">{payment.invoice_number}</span>
                </td>
                <td className="py-3">{payment.customer_name}</td>
                <td className="py-3 font-semibold">${payment.amount.toLocaleString()}</td>
                <td className="py-3">
                  <div className="flex items-center gap-1">
                    <Calendar size={14} className="text-gray-400" />
                    <span className="text-sm">
                      {payment.payment_date || payment.due_date}
                    </span>
                  </div>
                </td>
                <td className="py-3">
                  <span className="text-sm text-gray-300">
                    {payment.payment_method || '-'}
                  </span>
                </td>
                <td className="py-3">
                  <div className="flex items-center gap-2">
                    <span className={`w-2 h-2 rounded-full ${getStatusColor(payment.status)}`}></span>
                    <span className="text-sm capitalize">{payment.status}</span>
                    {getStatusIcon(payment.status)}
                  </div>
                </td>
                <td className="py-3">
                  <span className="text-sm text-gray-400 font-mono">
                    {payment.reference || '-'}
                  </span>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {filteredPayments.length === 0 && (
        <div className="text-center py-8 text-gray-400">
          No payments found matching your criteria
        </div>
      )}
    </div>
  );
};

export default PaymentHistory;
